INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(95379, 'ruRU', '', 'Эй, Порша! Пошевеливайся, сестрёнка!', 24330),
(95381, 'ruRU', '', 'Спасибо — всем вам. Приготовьтесь все. Это будет нелегко.', 24330),
(95386, 'ruRU', '', 'Держитесь рядом! Вот и началось!', 24330),
(95397, 'ruRU', '', 'Я вижу тебя, $n. Каков план?', 24330),
(95415, 'ruRU', '', 'Разрушение этого барьера потребует огромной доли моей силы. Боюсь, после этого я не смогу тебе помогать.', 24330),
(95417, 'ruRU', '', 'Здесь следы. Быстрокрылый, должно быть, пошёл этим путём!', 24330),
(95420, 'ruRU', '', 'Герой! Отомсти за Быстрокрылого!', 24330),
(95433, 'ruRU', '', 'Спасибо, герой. Я не справился бы с этим в одиночку.', 24330),
(95457, 'ruRU', '', 'Там снаружи война. А это значит — жизни, которые можно спасти, и деньги, которые можно заработать, $n!\n\nЧто скажешь, если возьмёшь мой нитро-электрический стартер и поможешь Громилам на передовой очнуться? Не забудь оставить им счёт!', 24330),
(95458, 'ruRU', '', 'Они ещё не мертвы, $n. А значит — они потенциальные клиенты!\n\nВсё просто. Берёшь мой нитро-электрический стартер и применяешь его на Громилах, которые выглядят неважно. Потом они платят мне! Я разбогатею!', 24330),
(95470, 'ruRU', '', 'Даже величайшим героям порой нужно отдыхать.', 24330),
(95485, 'ruRU', '', 'Доблестная жертва! Но твой час ещё не настал...', 24330),
(95486, 'ruRU', '', 'Следи за небом. Инферналы могут снова посыпаться в любой момент.', 24330),
(95487, 'ruRU', '', 'Я вживлю три осколка слоистой скверны в твою добывающую руку: один в плечо, один в локоть и один в запястье. Осколки небольшие, но, тем не менее, зазубренные.$b$bБудет немного больно.', 24330),
(95488, 'ruRU', '', 'Ты справился довольно неплохо.$b$bСледующий пойдёт в локоть. Готов?', 24330),
(95489, 'ruRU', '', 'Мы почти закончили. Как часто бывает, три — волшебное число. Тебе не захочется меньше слоистой скверны в теле... и уж точно не захочется больше.$b$bПоследний кусок пойдёт прямо в запястье. Готов?', 24330),
(95490, 'ruRU', '', 'Понятно. Риск велик... но если хочешь повысить свои навыки горного дела, другого пути нет.', 24330),
(95491, 'ruRU', '', 'Тогда не трать моё время. Возвращайся добывать лей-камень.', 24330),
(95492, 'ruRU', '', 'Мы почти закончили процедуру, шахтёр. Отступать сейчас уже нет смысла.', 24330),
(95493, 'ruRU', '', 'Мы, охотники на демонов, балансируем на опасной грани. Только ты можешь определить, где проходит эта грань.', 24330),
(95532, 'ruRU', '', 'Передай Ночной Гриве, что я всё ещё жив благодаря твоей помощи.', 24330),
(95534, 'ruRU', '', 'Мои сёстры где-то там, $p. Теперь они больше демоны, чем эльфы, но всё ещё шахтёры. Дай мне знать, если увидишь какой-то их след в своих странствиях.', 24330),
(95540, 'ruRU', '', 'Да?', 24330),
(95542, 'ruRU', '', 'Скажи мне, когда будешь готов разделиться.', 24330),
(95547, 'ruRU', '', 'А твой корабль уже обречён!', 24330),
(95553, 'ruRU', '', 'Постой! У неё может быть важная информация!', 24330),
(95554, 'ruRU', '', 'Так много летучих мышей...', 24330),
(95565, 'ruRU', '', 'Мы найдём кого-то, кто знает о Столпах Созидания. Даю слово.', 24330),
(95566, 'ruRU', '', 'Тебе рады в том укрытии, что мы можем предложить, $c.', 24330),
(95573, 'ruRU', '', 'Мы с Дуротаном поговорили. Я буду сопровождать твой морской десант и защищать тебя, пока мы закрепляемся в джунглях Танаана.$b$bЯ готов. А ты?', 24330),
(95580, 'ruRU', '', '|cFFFF0000%s|r пытается снять с себя все вредоносные эффекты!', 24330),
(95581, 'ruRU', '', 'Я поговорил с остальными экзархами, и всё готово. Я буду сопровождать твою морскую миссию и поддерживать тебя, пока мы устраиваем тыловую базу. Маладаар вызвался возглавить отвлекающий штурм у главных ворот.$b$bЯ готов настолько, насколько вообще могу быть. А ты?', 24330),
(95583, 'ruRU', '', 'Да. Дренеи поведут штурм главных ворот, пока твой флот обходит с тыла.', 24330),
(95586, 'ruRU', '', 'Прямо к северу отсюда есть древний синий дракон. Если кто и знает о Столпах, так это он.', 24330),
(95593, 'ruRU', '', 'Да, мой повелитель. Лагеря готовятся прямо сейчас.', 24330),
(95594, 'ruRU', '', 'А тем временем тебе стоит закончить свои дела с Кейном.', 24330),
(95595, 'ruRU', '', 'Наша сила не знает равных. Эти существа ещё не выдержали ни одного нашего натиска.', 24330),
(95596, 'ruRU', '', 'Наша хватка расширяется над этими землями. Знания скоро будут нашими.', 24330),
(95597, 'ruRU', '', 'Поистине хрупкая планета. Её обитатели весьма... уязвимы.', 24330),
(95605, 'ruRU', '', 'Выдвигаемся!', 24330);
